        try container.encode(self.toLocalTime, forKey: JSONCodingKey("toLocalTime"))
        try container.encode(self.coveredHours, forKey: JSONCodingKey("coveredHours"))
        try container.encode(self.minC, forKey: JSONCodingKey("minC"))
        try container.encode(self.maxC, forKey: JSONCodingKey("maxC"))
        try container.encode(self.apparentMinC, forKey: JSONCodingKey("apparentMinC"))
        try container.encode(self.apparentMaxC, forKey: JSONCodingKey("apparentMaxC"))
        try container.encode(self.maxPrecipitationProbabilityPct, forKey: JSONCodingKey("maxPrecipitationProbabilityPct"))
        try container.encode(self.precipitationMm, forKey: JSONCodingKey("precipitationMm"))
        try container.encode(self.maxWindGustKmh, forKey: JSONCodingKey("maxWindGustKmh"))
    }
}
